-- Karvaan v2: presentation only. Legacy requests/snapshots remain v1.
-- Frozen labels enter the digest in the existing issuance transaction.
grant carrier_documents,carrier_security to postgres;
create or replace function private.karvaan_output_v2(source jsonb) returns jsonb
language plpgsql immutable security invoker set search_path='' as $$
declare dictionary jsonb:='{"Karvaan": "کارواں", "Ask your administrator to configure this installation for staff sign-in.": "عملے کے داخلے کے لیے اس تنصیب کی ترتیب اپنے منتظم سے کروائیں۔", "Invalid business year": "کاروباری سال درست نہیں ہے", "Invalid calendar date": "تاریخ درست نہیں ہے", "Expected YYYY-MM-DD": "تاریخ YYYY-MM-DD کی صورت میں درکار ہے", "Expected a decimal string with at most two places": "اعشاری رقم درج کریں جس میں زیادہ سے زیادہ دو اعشاری ہندسے ہوں", "Money must be a decimal string": "رقم اعشاری متن کی صورت میں ہونی چاہیے", "Expected UUID": "UUID درکار ہے", "Current password verification failed. Check the temporary password or contact your administrator.": "موجودہ پاس ورڈ کی تصدیق نہیں ہوئی۔ عارضی پاس ورڈ چیک کریں یا اپنے منتظم سے رابطہ کریں۔", "Your account session was rejected. Sign out and sign in again.": "آپ کا اکاؤنٹ سیشن قبول نہیں ہوا۔ خارج ہو کر دوبارہ داخل ہوں۔", "Account access could not be verified. Contact your administrator.": "اکاؤنٹ تک رسائی کی تصدیق نہیں ہو سکی۔ اپنے منتظم سے رابطہ کریں۔", "Password change could not be prepared. Contact your administrator.": "پاس ورڈ کی تبدیلی تیار نہیں ہو سکی۔ اپنے منتظم سے رابطہ کریں۔", "The account service rejected the operation. Contact your administrator.": "اکاؤنٹ سروس نے کارروائی قبول نہیں کی۔ اپنے منتظم سے رابطہ کریں۔", "Check the account fields. New passwords must contain 12 to 128 characters.": "اکاؤنٹ کے خانے چیک کریں۔ نیا پاس ورڈ 12 سے 128 حروف پر مشتمل ہونا چاہیے۔", "Windows configuration location unavailable.": "Windows کی ترتیبات کا مقام دستیاب نہیں ہے۔", "Invalid public configuration.": "عوامی ترتیبات درست نہیں ہیں۔", "Isolated local test configuration required.": "الگ مقامی آزمائشی ترتیبات درکار ہیں۔", "Isolated test backend identity mismatch.": "الگ آزمائشی بیک اینڈ کی شناخت مطابقت نہیں رکھتی۔", "Invalid backend configuration.": "بیک اینڈ کی ترتیبات درست نہیں ہیں۔", "Invalid business identifier.": "کاروبار کا شناختی نمبر درست نہیں ہے۔", "A public project key is required.": "منصوبے کی عوامی کلید درکار ہے۔", "Enter a valid username.": "درست صارف نام درج کریں۔", "Account unavailable.": "اکاؤنٹ دستیاب نہیں ہے۔", "Account operation failed.": "اکاؤنٹ کی کارروائی ناکام ہو گئی۔", "Run backups on the configured administrator Windows PC.": "بیک اپ مقرر کردہ منتظم کے Windows کمپیوٹر پر چلائیں۔", "Administrator Windows helper is not configured.": "منتظم کے Windows معاون کی ترتیبات مکمل نہیں ہیں۔", "Install and configure the separate administrator backup helper first. See the backup setup guide.": "پہلے منتظم کا الگ بیک اپ معاون نصب کریں اور اس کی ترتیبات مکمل کریں۔ بیک اپ کی رہنمائی دیکھیں۔", "Personal funds advanced": "ذاتی رقم پیشگی دی گئی", "Payer personally bears this cost": "ادا کرنے والا یہ خرچ ذاتی طور پر برداشت کرتا ہے", "Held trip funds": "ٹرپ کی رقم زیرِ تحویل", "Enter a positive amount and notes.": "صفر سے زیادہ رقم اور تفصیل درج کریں۔", "Review payer, cost bearer and funding source.": "ادا کرنے والے، اخراجات کے ذمہ دار اور رقم کے ذریعے کا جائزہ لیں۔", "Confirm the agreed owner settlement offset.": "مالک کے تصفیے میں طے شدہ غیر نقد ایڈجسٹمنٹ کی تصدیق کریں۔", "Allocate the exact offset and held-funds spending separately.": "غیر نقد ایڈجسٹمنٹ اور زیرِ تحویل رقم کے خرچ کی درست رقم الگ الگ مختص کریں۔", "Receipt must be at most 5 MB.": "رسید کی فائل زیادہ سے زیادہ 5 MB ہو سکتی ہے۔", "Expense remains posted. Receipt attachment failed.": "خرچ بدستور درج ہے۔ رسید منسلک نہیں ہو سکی۔", "Choose actual payer/recipient and enter a reason.": "اصل ادا کرنے والا اور وصول کرنے والا منتخب کریں اور وجہ درج کریں۔", "Enter explicit allocations and select held sources.": "واضح مختص رقوم درج کریں اور زیرِ تحویل رقم کے ذرائع منتخب کریں۔", "Enter a correction reason up to 500 characters.": "درستگی کی وجہ زیادہ سے زیادہ 500 حروف میں درج کریں۔", "Agreed brokerage must be within the cancellation charge and have a broker.": "طے شدہ کمیشن منسوخی کے کرایے سے زیادہ نہیں ہو سکتا اور بروکر منتخب ہونا چاہیے۔", "Explicitly review every dependent settlement.": "ہر متعلقہ تصفیے کا